#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, k;
    cin >> n >> k;
    string s;
    cin >> s;
    int ans = 0;
    string t = string(k, 'O');
    for (int i = 0; i < n - k + 1; ++i) {
        if (s.substr(i, k) == t) {
            ans++;
            for (int j = i; j < i + k; j++) {
                s[j] = 'X';
            }
        }
    }
    cout << ans << endl;
}

n, k = map(int, input().split())
s = list(input())
ans = 0
t = 'O' * k

for i in range(n - k + 1):
    if s[i:i + k] == list(t):
        ans += 1
        for j in range(i, i + k):
            s[j] = 'X'

print(ans)
